const getCategoryTrends = `-- name: GetCategoryTrends :many
WITH current_period AS (
    SELECT
        transactions.category_id,
        SUM(transactions.amount_paise)::BIGINT AS total_paise
    FROM transactions
    WHERE transactions.user_id = $1
        AND transactions.date >= $2
        AND transactions.date < $3
        AND transactions.type = 'EXPENSE'
    GROUP BY transactions.category_id
),
previous_period AS (
    SELECT
        transactions.category_id,
        SUM(transactions.amount_paise)::BIGINT AS total_paise
    FROM transactions
    WHERE transactions.user_id = $1
        AND transactions.date >= $4
        AND transactions.date < $5
        AND transactions.type = 'EXPENSE'
    GROUP BY transactions.category_id
)
SELECT
    COALESCE(categories.name, 'Uncategorised') AS category_name,
    COALESCE(categories.icon, '') AS category_icon,
    COALESCE(current_period.total_paise, 0)::BIGINT AS current_paise,
    COALESCE(previous_period.total_paise, 0)::BIGINT AS previous_paise,
    (COALESCE(current_period.total_paise, 0) - COALESCE(previous_period.total_paise, 0))::BIGINT AS difference_paise
FROM current_period
FULL OUTER JOIN previous_period ON previous_period.category_id = current_period.category_id
LEFT JOIN categories ON categories.id = COALESCE(current_period.category_id, previous_period.category_id)
ORDER BY current_paise DESC, category_name ASC
`

type GetCategoryTrendsParams struct {
	UserID            pgtype.UUID        `json:"user_id"`
	CurrentStartDate  pgtype.Timestamptz `json:"current_start_date"`
	CurrentEndDate    pgtype.Timestamptz `json:"current_end_date"`
	PreviousStartDate pgtype.Timestamptz `json:"previous_start_date"`
	PreviousEndDate   pgtype.Timestamptz `json:"previous_end_date"`
}

type GetCategoryTrendsRow struct {
	CategoryName    string `json:"category_name"`
	CategoryIcon    string `json:"category_icon"`
	CurrentPaise    int64  `json:"current_paise"`
	PreviousPaise   int64  `json:"previous_paise"`
	DifferencePaise int64  `json:"difference_paise"`
}

func (q *Queries) GetCategoryTrends(ctx context.Context, arg GetCategoryTrendsParams) ([]GetCategoryTrendsRow, error) {
	rows, err := q.db.Query(ctx, getCategoryTrends,
		arg.UserID,
		arg.CurrentStartDate,
		arg.CurrentEndDate,
		arg.PreviousStartDate,
		arg.PreviousEndDate,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetCategoryTrendsRow
	for rows.Next() {
		var i GetCategoryTrendsRow
		if err := rows.Scan(
			&i.CategoryName,
			&i.CategoryIcon,
			&i.CurrentPaise,
			&i.PreviousPaise,
			&i.DifferencePaise,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

