const getRecurringCandidates = `-- name: GetRecurringCandidates :many
WITH merchant_stats AS (
    SELECT
        merchant_norm,
        type,
        COUNT(*) as occurrence_count,
        MIN(date)::TIMESTAMPTZ as first_date,
        MAX(date)::TIMESTAMPTZ as last_date,
        AVG(amount_paise) as avg_amount,
        STDDEV(amount_paise) as stddev_amount
    FROM transactions
    WHERE transactions.user_id = $1
      AND transactions.merchant_norm IS NOT NULL
      AND transactions.merchant_norm != ''
    GROUP BY transactions.merchant_norm, transactions.type
    HAVING COUNT(*) >= 3
),
existing_rules AS (
    SELECT merchant_norm FROM recurring_rules WHERE recurring_rules.user_id = $1 AND active = true
)
SELECT
    f.merchant_norm,
    f.type,
    f.occurrence_count::INT,
    f.first_date,
    f.last_date,
    f.avg_amount::BIGINT as avg_amount,
    COALESCE(f.stddev_amount, 0)::FLOAT as stddev_amount
FROM merchant_stats f
LEFT JOIN existing_rules r ON f.merchant_norm = r.merchant_norm
WHERE r.merchant_norm IS NULL
  AND (f.stddev_amount IS NULL OR (f.stddev_amount / f.avg_amount) <= 0.10)
`

type GetRecurringCandidatesRow struct {
	MerchantNorm     string             `json:"merchant_norm"`
	Type             string             `json:"type"`
	FOccurrenceCount int32              `json:"f_occurrence_count"`
	FirstDate        pgtype.Timestamptz `json:"first_date"`
	LastDate         pgtype.Timestamptz `json:"last_date"`
	AvgAmount        int64              `json:"avg_amount"`
	StddevAmount     float64            `json:"stddev_amount"`
}

func (q *Queries) GetRecurringCandidates(ctx context.Context, userID pgtype.UUID) ([]GetRecurringCandidatesRow, error) {
	rows, err := q.db.Query(ctx, getRecurringCandidates, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetRecurringCandidatesRow
	for rows.Next() {
		var i GetRecurringCandidatesRow
		if err := rows.Scan(
			&i.MerchantNorm,
			&i.Type,
			&i.FOccurrenceCount,
			&i.FirstDate,
			&i.LastDate,
			&i.AvgAmount,
			&i.StddevAmount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

